#include <stdio.h>
#include <limits.h>

#define MIN(a,b) ((a) < (b) ? (a) : (b))

int getMaxResponseTime(int m);

int res = INT_MAX;

int main() {
    int c;
    scanf("%d", &c);

    int t, m;
    for (int i = 0; i < c; i++) {
        scanf("%d %d", &t, &m);
        int respTime = t + getMaxResponseTime(m);
        res = MIN(res, respTime);
    }

    printf("%d\n", res);

    return 0;
}

int getMaxResponseTime(int m) {
    // Max Resp Code >= 128时，最大响应时间 = (mant | 0x10) << (exp + 3)；
    if(m >= 128) {
        // 将十进制数 m 转成 二进制字符串对应的整型数组，比如 m = 255时，bin[8] = {1, 1, 1, 1, 1, 1, 1, 1};
        int bin[8] = {0};

        int i = 7;
        while(m > 0) {
            bin[i--] = m % 2;
            m /= 2;
        }

        //    j     0  1  2  3  4  5  6  7
        // bin[] = {1, 1, 1, 1, 1, 1, 1, 1};
        // exp截取bin的 j:1~3 范围，注意对应范围当成一个新的二进制数，因此j=3的位置是2^0
        int exp = 0;
        for(int j=1; j<4; j++) {
            exp += bin[j] * (1 << (3 - j));
        }

        // mant截取bin的 j：4~7 范围，，注意对应范围当成一个新的二进制数，因此j=7的位置是2^0
        int mant = 0;
        for(int j=4; j<8; j++) {
            mant += bin[j] * (1 << (7 - j));
        }

        // 0x10 等价于 16
        return (mant | 16) << (exp + 3);
    } else {
        return m;
    }
}
